import random, math, statistics
from collections import Counter
seq="".join(l.strip() for l in open("region.fasta").read().split("\n")[1:] if l.strip())
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return "".join(comp[x] for x in reversed(s))

idx = {b:i for i,b in enumerate("ACGT")}
def to_int(s,k):
    v=0
    for ch in s: v=v*4+idx[ch]
    return v
def chi2(s,k):
    N=len(s)-k+1
    cnt=Counter(to_int(s[i:i+k],k) for i in range(N))
    p=[s.count(b)/len(s) for b in "ACGT"]
    exp=[];obs=[]
    for code in range(4**k):
        e=N; x=code
        for _ in range(k):
            e*=p[x%4]; x//=4
        exp.append(e); obs.append(cnt.get(code,0))
    return sum((o-e)**2/e for o,e in zip(obs,exp)), sum(1 for o in obs if o==0)

obs={}
for k in (3,4,5,6):
    c,missing=chi2(seq,k); obs[k]=(c,missing)
print("observed:", obs)

